import {respond,skills,applyProposal} from './agents.mjs';
import {defaults,node,preset,presetNames,architectures,operatingSystems,devices,backends,validate,assessGroup,buildConfig,toYAML,markdown,importConfig,sources,RULESET} from './model.mjs';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={commands:'Local commands',agents:'Agent workspace',overview:'About TriX',configure:'Configure environment',compare:'Compare scenarios',plan:'Technical configuration',reference:'Standards & criteria'};
let state=defaults(),comparisons=[],active='overview',format='json',selectedPreset='hybrid',matrixGroup=0,toastTimer,previousScenario=null;
try{const saved=localStorage.getItem('trix.environment.v1');if(saved)state=importConfig(saved);const savedCompare=JSON.parse(localStorage.getItem('trix.compare.v1')||'[]');if(Array.isArray(savedCompare))comparisons=savedCompare.slice(0,4).map(c=>importConfig(JSON.stringify(c)));}catch{localStorage.removeItem('trix.environment.v1');localStorage.removeItem('trix.compare.v1');}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function persist(){try{const c={schema:'trix.environment-planning/v1',planning_input:state};localStorage.setItem('trix.environment.v1',JSON.stringify(c));localStorage.setItem('trix.compare.v1',JSON.stringify(comparisons.map(s=>({schema:'trix.environment-planning/v1',planning_input:s}))));}catch{toast('Local saving is unavailable. Export JSON to preserve your scenario.');}}
function options(map,value){return Object.entries(map).map(([k,v])=>`<option value="${esc(k)}" ${k===value?'selected':''}>${esc(v)}</option>`).join('');}
function field(label,key,value,map,group=null,type='text',small='',extra=''){const id=(group===null?'env':group)+'-'+key;return `<div class="field ${extra}"><label for="${id}">${label}</label>${map?`<select id="${id}" data-key="${key}" ${group!==null?`data-group="${esc(group)}"`:''}>${options(map,value)}</select>`:`<input id="${id}" ${type==='number'?`min="${key==='count'||key==='ram'?1:0}" max="${key==='count'?1024:1048576}" step="1"`:'maxlength="120"'} type="${type}" data-key="${key}" ${group!==null?`data-group="${esc(group)}"`:''} value="${esc(value)}">`}${small?`<small>${small}</small>`:''}</div>`;}
function statusBadge(r){return `<span class="badge ${r.errors?'red':r.warnings?'amber':'green'}">${r.errors?'Incompatible':r.warnings?'Conditional':'Coherent'}</span>`;}
function heading(title,subtitle,actions='',eyebrow='CONFIGURATION STUDIO'){return `<div class="page-heading"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function cardHead(n,title,description='',right=''){return `<div class="card-head"><div><h2>${n?`<span class="step">${n}</span>`:''}${title}</h2>${description?`<p>${description}</p>`:''}</div>${right}</div>`;}
function stats(r){const families=new Set(state.groups.map(g=>g.arch));return `<div class="stats"><div class="stat"><div><span class="label">Execution groups</span><strong>${String(state.groups.length).padStart(2,'0')}</strong> <small>/ ${r.total||0} nodes</small></div><span class="stat-icon">▧</span></div><div class="stat"><div><span class="label">Architectures</span><strong>${String(families.size).padStart(2,'0')}</strong> <small>ISA</small></div><span class="stat-icon">◇</span></div><div class="stat"><div><span class="label">Selected backends</span><strong>${String(new Set(state.groups.map(g=>g.backend)).size).padStart(2,'0')}</strong> <small>ENGINES</small></div><span class="stat-icon">⌘</span></div><div class="stat"><div><span class="label">Scenario validation</span>${statusBadge(r)}<small style="display:block;margin-top:5px">${r.errors} BLOCKERS · ${r.warnings} CONDITIONS</small></div><span class="stat-icon">✓</span></div></div>`;}
function validationPanel(r){return `<div class="card"><div class="validation-head"><p class="eyebrow">LIVE VALIDATION</p>${statusBadge(r)}<h2>${r.errors?'Review combinations':r.warnings?'Ready for planning':'Coherent plan'}</h2><p>${r.errors?'Resolve blockers to generate your configuration. Each diagnostic explains the cause and how to fix it.':'This scenario can guide implementation. Qualification requires exact versions and evidence from the target environment.'}</p></div><div class="validation-score"><div><strong>${r.errors}</strong>Blockers</div><div><strong>${r.warnings}</strong>Conditions</div><div><strong>0</strong>Qualified profiles</div></div><div class="issue-list" aria-label="Diagnostics">${[...r.issues].sort((a,b)=>(a.level==='error'?0:1)-(b.level==='error'?0:1)).map(i=>`<div class="issue ${i.level}"><div class="issue-title"><span class="issue-symbol">${i.level==='error'?'×':'!'}</span><code>${esc(i.code)}</code></div>${i.group?`<small>${esc(state.groups.find(g=>g.id===i.group)?.name||i.group)}</small>`:''}<p>${esc(i.message)}</p><details><summary>How to resolve · ${esc(i.ref)}</summary><p>${esc(i.fix)}</p></details></div>`).join('')||'<p class="right-note">No planning conflicts. Implementation still requires qualification.</p>'}</div><div class="validation-foot"><button class="primary" data-action="generate" ${r.errors?'disabled':''}>Generate technical configuration <span>↗</span></button><p class="footnote">${r.errors?'Export blocked by incompatible combinations.':'Planning export includes explicit conditions. It does not execute tasks or reserve resources.'}</p></div></div>`;}
function topology(){return `<div class="card">${cardHead('','Proposed topology','Vendor-independent logical roles')}<div class="topology" aria-label="Web control client to authorised coordinator to execution groups"><div class="topology-node">Interaction · web client</div><div class="topology-line"></div><div class="topology-node">Coordination · authorised core</div><div class="topology-line"></div><div class="topology-groups">${state.groups.map(g=>`<div class="topology-node">${esc(g.name)} ×${g.count}</div>`).join('')}</div></div></div>`;}
function groupCard(g,i){const issues=assessGroup(g,state),r={errors:issues.filter(x=>x.level==='error').length,warnings:issues.filter(x=>x.level==='warning').length};return `<article class="group" data-group-card="${esc(g.id)}"><div class="group-title"><h3><span class="index">G${String(i+1).padStart(2,'0')}</span>${esc(g.name)}</h3><div>${statusBadge(r)} <button class="ghost" data-action="remove" data-id="${esc(g.id)}" aria-label="Remove ${esc(g.name)}" ${state.groups.length===1?'disabled':''}>×</button></div></div><div class="group-content"><div class="field-grid">${field('Group name','name',g.name,null,g.id)}${field('Node count','count',g.count,null,g.id,'number','Nodes sharing this profile')}${field('CPU family','vendor',g.vendor,{amd:'AMD CPU',intel:'Intel CPU',apple:'Apple silicon',qualcomm:'Qualcomm CPU',arm:'Other ARM',other:'Other / generic'},g.id)}${field('Architecture / ISA','arch',g.arch,architectures,g.id)}${field('Operating system','os',g.os,operatingSystems,g.id)}${field('ABI / binary runtime','abi',g.abi,{gnu:'GNU / glibc',musl:'musl',msvc:'Windows MSVC',darwin:'Apple Darwin',bionic:'Android Bionic',wasm:'WebAssembly',bsd:'FreeBSD'},g.id)}${field('Execution device','device',g.device,devices,g.id)}${field('Backend / engine','backend',g.backend,backends,g.id)}${field('RAM per node (GiB)','ram',g.ram,null,g.id,'number')}${field('Device memory (GiB)','vram',g.vram,null,g.id,'number',g.device==='apple'?'Shared with RAM; do not add together.':'Per device/replica; not pooled across nodes.')}</div><div class="group-bottom"><details><summary>Exact versions & hardware <span>+ Pin software & hardware</span></summary><div class="field-grid">${field('OS / kernel version','osVersion',g.osVersion,null,g.id)}${field('Device SKU / CPU model','deviceModel',g.deviceModel,null,g.id)}${field('Driver / firmware version','driver',g.driver,null,g.id)}${field('Backend version','backendVersion',g.backendVersion,null,g.id)}</div></details></div></div></article>`;}
const agentRoles=[
 {id:'requirements',name:'Requirements analyst',area:'Intent → constraints',description:'Clarifies workload, target environment, data policy and missing inputs.',deliverable:'Requirements brief',scope:'Read project context; propose requirements.'},
 {id:'platform',name:'Platform specialist',area:'Hardware & backend',description:'Maps target profiles and checks ISA, OS, ABI, device and engine combinations.',deliverable:'Compatibility assessment',scope:'Read profiles; propose target changes.'},
 {id:'planner',name:'Execution planner',area:'Plan & dependencies',description:'Prepares task order, adapter requirements and implementation milestones.',deliverable:'Execution proposal',scope:'Draft plans; no machine access.'},
 {id:'validator',name:'Validation specialist',area:'Correctness & evidence',description:'Reviews blockers, qualification gates, tests and acceptance evidence.',deliverable:'Validation checklist',scope:'Run permitted checks; report evidence.'},
 {id:'security',name:'Security reviewer',area:'Policy & permissions',description:'Reviews data boundaries, credential references and requested privileges.',deliverable:'Policy review',scope:'Review only; cannot widen permissions.'},
 {id:'documenter',name:'Documentation specialist',area:'English deliverables',description:'Consolidates decisions into traceable English implementation documentation.',deliverable:'Implementation brief',scope:'Prepare draft artifacts.'}
];
let agentPrompt='',agentDraft=false,selectedAgent='requirements';
function agents(){const r=validate(state);return heading('A single conversation. Coordinated expertise.','Prepare an intent, inspect the delegation model and review the current environment before execution is connected.',`<span class="badge purple">INTERACTIVE DESIGN · NO MODEL CONNECTED</span>`,'AGENT WORKSPACE')+`<div class="agent-layout"><section class="card conversation">${cardHead('','Orchestrator','Your single point of contact · subagents report through her')}<div class="card-body"><div class="agent-message"><span class="agent-avatar">T×</span><div><strong>TriX Orchestrator</strong><p>Describe the outcome you want, your available hardware and any constraints. This design workspace can capture a brief and inspect the current configuration. Live model reasoning, delegation and execution are not connected yet.</p></div></div><div class="prompt-examples"><button class="secondary" data-example="Plan an offline inference workflow across Apple silicon and an NVIDIA server. Keep all data local.">Offline hybrid workflow</button><button class="secondary" data-example="Compare a CPU-only environment with a GPU environment and identify qualification tests.">Compare execution options</button></div><label class="field-label" for="agent-prompt">What would you like TriX to help you achieve?</label><textarea id="agent-prompt" rows="5" maxlength="6000" placeholder="Describe your goal, hardware, workload and constraints…">${esc(agentPrompt)}</textarea><div class="composer-actions"><small>Draft stays in this session. No prompt is sent to a provider.</small><button class="primary" data-action="prepare-brief">Prepare review brief ↗</button></div>${agentDraft?`<div class="agent-brief" role="status"><p class="eyebrow">LOCAL REVIEW BRIEF · NOT AN AI RESPONSE</p><h3>Intent captured for review</h3><p class="intent-copy">${esc(agentPrompt)}</p><p><strong>Environment:</strong> ${esc(state.name)} · ${state.groups.length} groups · ${r.errors} blockers · ${r.warnings} conditions.</p><p>The proposed roles below define a future delegation path. No subagent has run and the prompt has not changed your configuration.</p><div class="actions"><button class="secondary" data-go="configure">Review environment</button><button class="secondary" data-go="plan">Inspect technical plan</button></div></div>`:''}</div></section><aside><section class="card">${cardHead('','Execution boundary')}<div class="card-body"><div class="reference-item"><strong>Connection · Not configured</strong><p>Connect a permitted model and tool runtime before enabling live dialogue or task execution.</p></div><div class="reference-item"><strong>Authority · Draft only</strong><p>No credentials, machine access, external messages or infrastructure changes are available in this design.</p></div><div class="reference-item"><strong>Current validation</strong><p>${r.errors} blockers · ${r.warnings} conditions. Results come from the existing deterministic configurator.</p></div></div></section><section class="card">${cardHead('','Planned task lifecycle')}<div class="card-body"><ol class="steps-list"><li><strong>01</strong>Clarify intent and constraints</li><li><strong>02</strong>Delegate scoped specialist work</li><li><strong>03</strong>Validate and reconcile findings</li><li><strong>04</strong>Review the proposed actions</li><li><strong>05</strong>Execute within granted authority</li><li><strong>06</strong>Verify results and record evidence</li></ol></div></section></aside></div><div class="subheading"><h2>Specialist subagents</h2><span class="source-time">PROPOSED ROLES · NOT RUNNING</span></div><div class="agent-roster">${agentRoles.map(a=>`<button class="agent-role ${selectedAgent===a.id?'selected':''}" data-agent="${a.id}" aria-pressed="${selectedAgent===a.id}"><span class="badge purple">PROPOSED</span><h3>${a.name}</h3><p>${a.area}</p><small>${a.description}</small></button>`).join('')}</div>${agentDetail()}<section class="card">${cardHead('','Governance & audit','A separate reporting path for independent review')}<div class="card-body"><div class="governance-grid"><div><h3>Coordination</h3><p>Global Coordinator → Orchestrator → project SubOrchestrator → scoped subagents. Subagents return findings through the orchestration chain; direct peer-to-peer communication is excluded.</p></div><div><h3>Independent audit</h3><p>Project Auditor → Global Auditor → human owner. Auditors keep a separate evidence record and do not approve their own implementation work.</p></div><div><h3>Visible task records</h3><p>The connected runtime should show delegated scope, status, tool calls, evidence, budget, cancellation and permission gates. No execution history is fabricated in this prototype.</p></div></div></div></section>`;}
function agentDetail(){const a=agentRoles.find(x=>x.id===selectedAgent);return `<section class="card agent-detail">${cardHead('',a.name,'Role contract preview')}<div class="card-body governance-grid"><div><strong>Expected output</strong><p>${a.deliverable}</p></div><div><strong>Permitted scope</strong><p>${a.scope}</p></div><div><strong>Reporting & status</strong><p>Reports to the project orchestration layer. Proposed · no live task assigned.</p></div></div></section>`;}
function overview(){return heading('One intent. Explicit execution choices.','TriX is a proposed language and execution-contract layer for describing work independently of a single hardware vendor, operating system or backend. Her goal is to turn intent into inspectable plans that adapters can validate and execute.',`<button class="primary" data-go="configure">Explore an environment ↗</button>`,'MEET TRIX')+`<section class="mission"><p class="eyebrow">WHY SHE EXISTS</p><h2>Changing infrastructure should not mean redesigning the entire workflow.</h2><p>AI and compute projects span local machines, servers, cloud services and clusters. Each environment brings different instruction sets, drivers, memory limits and execution engines. TriX aims to make those differences explicit in a shared planning and execution model, while keeping platform-specific behavior behind qualified adapters.</p><span class="badge purple">LANGUAGE & RUNTIME: PROPOSED</span></section><div class="reference-grid"><section class="card">${cardHead('','The problems she addresses')}<div class="card-body">${[
['Fragmented integrations','Teams repeatedly connect the same workflow to different engines and infrastructure. A common contract aims to reduce duplicated integration work.'],
['Compatibility discovered too late','A GPU name alone says little about model support. TriX makes ISA, OS, ABI, driver, backend, model and version requirements visible before execution.'],
['Confusion about distributed work','Independent tasks can use heterogeneous workers. A single distributed operation needs a compatible collective implementation and a qualified topology.'],
['Hidden operational assumptions','Memory, data residency, offline operation, recovery and reproducibility need explicit constraints and evidence rather than implicit promises.']].map(([a,b])=>`<div class="reference-item"><strong>${a}</strong><p>${b}</p></div>`).join('')}</div></section><section class="card">${cardHead('','What she is designed to enable','Design goals · implementation and qualification required')}<div class="card-body">${[
['Describe work once, target deliberately','Express tasks and constraints, then resolve them against available platform and adapter capabilities. Portability remains conditional on supported operations.'],
['Combine local and remote resources','Plan independent stages across CPU, Apple silicon, NVIDIA, AMD, Intel and provider services, subject to policy and adapter support.'],
['Extend through an SDK','Introduce new execution engines and hardware profiles through versioned capability contracts, validation and qualification tests.'],
['Inspect decisions and failures','Keep execution choices, unsupported combinations and unresolved conditions traceable for developers, operators and implementing agents.']].map(([a,b])=>`<div class="reference-item"><strong>${a}</strong><p>${b}</p></div>`).join('')}</div></section></div><section class="card">${cardHead('','A concrete example','A heterogeneous workflow, not pooled device memory')}<div class="card-body"><p class="example-text">A team wants a local Apple machine for one model stage, an NVIDIA server for another, and a remote provider for an optional task. TriX is intended to describe the tasks and their contracts, select compatible adapters, enforce where data may go and report when a requested execution path is unavailable.</p><div class="note-box">In this lab, you can model the target groups, compare backend constraints and export a planning configuration. The lab does not execute this workflow. Apple and NVIDIA memory are not combined into one shared pool.</div></div></section><div class="reference-grid"><section class="card">${cardHead('','Project objectives')}<div class="card-body"><ol class="steps-list"><li><strong>01</strong>Establish precise, versioned task and capability contracts.</li><li><strong>02</strong>Build an SDK, verifier and local CPU reference executor.</li><li><strong>03</strong>Demonstrate distributed execution and a control API.</li><li><strong>04</strong>Validate extensibility with an additional backend.</li><li><strong>05</strong>Define the language grammar and prove source-to-plan equivalence.</li><li><strong>06</strong>Expand qualified targets using correctness, failure-handling and performance evidence.</li></ol></div></section><section class="card">${cardHead('','What is available today')}<div class="card-body"><div class="reference-item"><strong>Available · Environment Lab</strong><p>Editable target profiles, compatibility rules, workload and policy constraints, up to four comparison snapshots, and JSON, YAML or Markdown planning exports.</p></div><div class="reference-item"><strong>Proposed · TriX language and runtime</strong><p>The compiler, execution SDK, adapters, scheduling, runtime policy enforcement and physical qualification are implementation objectives. This interface does not demonstrate that they exist.</p></div><div class="reference-item"><strong>Success means evidence</strong><p>Supported workloads must produce verified results on pinned target profiles, explain rejected paths, pass recovery and policy tests, and publish measured performance. Universal compatibility or automatic speed gains are not assumed.</p></div></div></section></div><section class="next-step"><div><h2>Explore where she could run.</h2><p>Choose a profile, define your workload and review the constraints.</p></div><button class="primary" data-go="configure">Open the configurator ↗</button><button class="secondary" data-go="reference">Read the criteria</button></section>`;}
function configure(){const r=validate(state);return heading('Design her execution environment.','Choose hardware, operating systems and execution engines. Resolve compatibility constraints and export an actionable technical plan.',`<button class="secondary" data-action="import">↥ Import</button><button class="secondary" data-action="snapshot">＋ Save for comparison</button>`) + stats(r)+`<nav class="workflow" aria-label="Configuration steps"><a href="#profiles"><b>01</b> Choose a profile</a><a href="#execution"><b>02</b> Define hardware</a><a href="#workload"><b>03</b> Set workload</a><a href="#policies"><b>04</b> Review policies</a></nav>${previousScenario?'<div class="undo-banner" role="status">Profile applied. Your previous scenario is available. <button class="secondary" data-action="undo-profile">Undo profile change</button></div>':''}<div class="main-grid"><div><section class="card" id="profiles">${cardHead('01','Start with a profile','Editable starting points · all profiles are proposed')}<div class="card-body"><div class="preset-row">${Object.entries(presetNames).map(([k,v])=>`<button class="preset ${selectedPreset===k?'selected':''}" data-preset="${k}">${v}</button>`).join('')}</div><p class="preset-hint">Applying a profile replaces your working scenario. Save a comparison snapshot to keep your current choices.</p></div></section><section class="card" id="execution">${cardHead('02','Define execution groups','Heterogeneous resources, shared execution contracts',`<span class="badge purple">SDK-FIRST</span>`)}<div class="card-body"><div class="field-grid" style="margin-bottom:21px">${field('Environment name','name',state.name,null,null,'text','','wide')}</div>${state.groups.map(groupCard).join('')}<button class="new-group" data-action="add" ${state.groups.length>=8?'disabled':''}>＋ Add execution group <span>· up to 8</span></button></div></section><section class="card" id="workload">${cardHead('03','Orchestration & workload','Resource management and execution engines are separate decisions')}<div class="card-body"><div class="field-grid">${field('Execution mode','mode',state.mode,{independent:'Independent tasks / pipeline',tensor:'Single operation · tensor parallel',data:'Training · data parallel'})}${field('Resource manager','manager',state.manager,{standalone:'Standalone executors',kubernetes:'Kubernetes',slurm:'Slurm'})}${field('Interconnect','fabric',state.fabric,{ethernet:'Ethernet / TCP',rdma:'RDMA / InfiniBand / RoCE',nvlink:'NVLink / NVSwitch · qualified fabric'})}${field('Operation type','operation',state.operation,{inference:'Model inference',training:'Training / fine-tuning',tools:'Tools / processing'})}${field('Artifact / model','model',state.model,null,null,'text','Specific identity; universal support is not implied.')}${field('Revision / digest','modelVersion',state.modelVersion,null)}${field('Required precision','precision',state.precision,{fp32:'FP32',fp16:'FP16',bf16:'BF16',int8:'INT8',int4:'INT4'})}${field('Required memory per replica (GiB)','memory',state.memory,null,null,'number','Total estimate, including caches and overhead.')}</div><div class="note-box" style="margin-top:18px">For independent tasks, every group must fit its assigned replica. Unified RAM, VRAM and memory from different nodes are not added together.</div></div></section><section class="card" id="policies">${cardHead('04','Policies & requirements','Scenario constraints for the future runtime to enforce')}<div class="card-body"><div class="field-grid">${field('Data policy','residency',state.residency,{local:'Local only · no remote processing',approved:'Remote approved · region requires qualification'})}</div>${[['offline','Fully offline operation','Blocks engines that depend on remote services.'],['checkpoint','Require checkpoint & resume','Adds a negotiation and testing requirement for each adapter.'],['deterministic','Require exact reproduction','Requires a reference oracle; equality across hardware is not assumed.']].map(([k,v,d])=>`<div class="check-row"><input id="${k}" type="checkbox" data-key="${k}" ${state[k]?'checked':''}><label for="${k}">${v}<small>${d}</small></label></div>`).join('')}</div></section><div class="save-note"><span></span>Saved in this browser only. Export JSON to transfer or preserve your scenario.</div></div><aside class="side-panel"><div id="live-validation" aria-live="polite">${validationPanel(r)}</div>${topology()}<p class="right-note"><strong>Compatibility depends on the full stack.</strong><br>ISA + OS + ABI + device + driver + engine + model + versions. A hardware family alone is not a qualified profile.</p></aside></div>`;}
function compare(){return heading('Compare your options.','Save up to four scenarios to compare constraints, topologies and implementation requirements.',`<button class="secondary" data-action="snapshot">＋ Save current scenario</button><button class="primary" data-go="configure">Back to configuration ↗</button>`,'SCENARIO COMPARISON')+(comparisons.length?`<div class="card compare-wrap"><table><thead><tr><th>DIMENSION</th>${comparisons.map((s,i)=>`<th>${esc(s.name)}<div class="table-actions"><button class="secondary" data-action="load" data-index="${i}">Open scenario</button><button class="ghost" data-action="delete-snapshot" data-index="${i}">Remove</button></div></th>`).join('')}</tr></thead><tbody>${[
 ['Status',s=>statusBadge(validate(s))],['Nodes / groups',s=>`${validate(s).total} nodes · ${s.groups.length} groups`],['Architectures',s=>[...new Set(s.groups.map(g=>architectures[g.arch]))].join('<br>')],['Operating systems',s=>[...new Set(s.groups.map(g=>operatingSystems[g.os]))].join('<br>')],['Backends',s=>s.groups.map(g=>esc(backends[g.backend])).join('<br>')],['RAM per node',s=>s.groups.map(g=>`${esc(g.name)}: ${g.ram} GiB`).join('<br>')],['Device memory / node',s=>s.groups.map(g=>`${esc(g.name)}: ${g.vram} GiB`).join('<br>')],['Topology',s=>esc(s.mode)+'<br>'+esc(s.manager)+' · '+esc(s.fabric)],['Policy',s=>`${s.offline?'Offline':'Network allowed'}<br>${esc(s.residency)}`],['Blockers',s=>`<strong>${validate(s).errors}</strong>`],['Unresolved conditions',s=>`<strong>${validate(s).warnings}</strong>`],['Evidence',s=>'Proposed · not qualified']
 ].map(([label,fn])=>`<tr><td>${label}</td>${comparisons.map(s=>`<td>${fn(s)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<div class="card empty"><span class="empty-icon">⇄</span><h2>Good decisions start with alternatives.</h2><p>Save your current scenario, choose another profile and save it too. Each snapshot retains its own validation results.</p><button class="primary" data-action="snapshot">Save first scenario</button></div>`)+matrix();}
function matrix(){matrixGroup=Math.min(matrixGroup,state.groups.length-1);const base=state.groups[matrixGroup];return `<div class="subheading"><h2>Backend compatibility matrix</h2><span class="source-time">POLICY & WORKLOAD INCLUDED</span></div><div class="card"><div class="matrix-controls"><label for="matrix-group">Reference group</label><select id="matrix-group">${state.groups.map((g,i)=>`<option value="${i}" ${i===matrixGroup?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><div class="compare-wrap"><table class="matrix"><thead><tr><th>Candidate backend</th><th>Compatibility</th><th>Primary diagnostic</th></tr></thead><tbody>${Object.entries(backends).map(([key,name])=>{const issues=assessGroup({...base,backend:key},state);const err=issues.filter(x=>x.level==='error'),warn=issues.filter(x=>x.level==='warning');return `<tr><td>${esc(name)}${base.backend===key?'<small>Selected in this scenario</small>':''}</td><td>${statusBadge({errors:err.length,warnings:warn.length})}</td><td>${esc((err[0]||warn[0])?.message||'Coherent planning combination; physical qualification remains required.')}</td></tr>`;}).join('')}</tbody></table></div><div class="card-body"><p class="footnote">The matrix holds device, ISA, OS, ABI and policies constant. Switching engines may also require a different device. This is not a performance ranking or hardware benchmark.</p></div></div>`;}
function planText(){const c=buildConfig(state);return format==='yaml'?toYAML(c):format==='brief'?markdown(c):JSON.stringify(c,null,2);}
function plan(){const r=validate(state);return heading('Turn decisions into a technical plan.','Inspect your decisions, unresolved conditions and required tests before handing the plan to an implementer.',`<button class="secondary" data-go="configure">← Edit environment</button>`,'TECHNICAL CONFIGURATION')+stats(r)+(r.errors?`<div class="card empty"><span class="empty-icon">×</span><h2>This configuration has ${r.errors} blocker${r.errors>1?'s':''}.</h2><p>Resolve incompatible combinations before generating a technical file.</p><button class="primary" data-go="configure">Review validation</button></div>`:`<div class="card"><div class="plan-toolbar"><div class="segmented" aria-label="Configuration format">${[['json','JSON'],['yaml','YAML'],['brief','Brief · EN']].map(([k,l])=>`<button data-format="${k}" class="${format===k?'active':''}">${l}</button>`).join('')}</div><div class="actions"><button class="secondary" data-action="copy">Copy</button><button class="primary" data-action="download">↓ Export ${format==='brief'?'Markdown':format.toUpperCase()}</button></div></div><div class="plan-notice">Proposed · ${r.warnings} unresolved conditions · 0 qualified profiles. This file uses the configurator planning schema, separate from the future TriX IR.</div><pre class="code" tabindex="0" aria-label="Technical configuration content"><code>${esc(planText())}</code></pre></div><div class="reference-grid"><section class="card">${cardHead('','Implementation sequence','Aligned with baseline v0.2')}<div class="card-body"><ol class="steps-list">${[['E0','Contracts, profile matrix and decisions'],['E1','SDK, verifier and local CPU executor'],['E2','Distributed reference and control API'],['E3','Third engine through the SDK'],['E4','Grammar and source-to-plan equivalence'],['E5','Expansion, qualification and optimization']].map(([a,b])=>`<li><strong>${a}</strong>${b}</li>`).join('')}</ol></div></section><section class="card">${cardHead('','Before qualification','A coherent plan does not establish execution evidence')}<div class="card-body"><div class="reference-item"><strong>Pin the environment</strong><p>Versions, SKU, firmware, drivers, ABI, models and operations.</p></div><div class="reference-item"><strong>Demonstrate failure handling</strong><p>Policy refusal, cancellation, restart, partition and recovery.</p></div><div class="reference-item"><strong>Measure & review</strong><p>Memory, precision, latency, capacity and independent review.</p></div></div></section></div>`);}
function reference(){return heading('Contracts before claims.','Criteria traced to the TriX v0.2 specification and vendor documentation.',`<span class="badge purple">RULESET ${RULESET}</span>`,'PLANNING FOUNDATION')+`<div class="reference-grid"><section class="card">${cardHead('','What this lab validates')}<div class="card-body">${[
 ['Complete target identity','ISA, CPU family, OS, ABI, device and engine are independent dimensions. x64, AMD64 and x86-64 refer to the same ISA.','PLT-001 · PLT-004'],['Distributed tasks ≠ a distributed operation','A pipeline can route independent tasks across Apple, NVIDIA, AMD and others. Joint computation requires a validated group.','ARQ-006 · INT-009'],['Separate managers and engines','Standalone, Kubernetes and Slurm manage execution and resources. They do not establish model compatibility with a GPU.','ARQ-005 · INT-001'],['Explicit authority and data policy','Offline and local-only policies reject remote services. The future runtime must enforce permissions and external credential references.','INT-007 · GOV-009'],['Evidence status','All profiles are proposed. Diagnostics flag assumptions and conditions; no scenario is marked as qualified.','NOR-007 · VER-008'],['Memory & precision','Memory estimates are per replica, not pooled across nodes. FP16, BF16 and quantization require model and operator tests.','LNG-012 · INT-006']
 ].map(([a,b,c])=>`<div class="reference-item"><strong>${a}</strong><p>${b}</p><span class="trace">${c}</span></div>`).join('')}</div></section><section class="card">${cardHead('','Sources & scope','Documentation consulted on 22 October 2026')}<div class="card-body">${sources.map(s=>`<div class="reference-item"><strong>${s.url?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${s.name} ↗</a>`:s.name}</strong><p>${esc(s.scope)}</p></div>`).join('')}</div></section><section class="card">${cardHead('','Scope of this release')}<div class="card-body"><div class="reference-item"><strong>Static planning</strong><p>This tool does not detect hardware, execute models, access machines or reserve resources. Actual compatibility requires complete environment snapshots and physical tests.</p></div><div class="reference-item"><strong>Conservative, extensible profiles</strong><p>Custom adapters, RISC-V, x86-32, POWER, IBM Z and BSD remain extension candidates. These planning rules do not represent all upstream support.</p></div><div class="reference-item"><strong>Browser-local persistence</strong><p>Scenarios and comparisons live in this browser storage. Export JSON to keep a copy or import it on another device.</p></div></div></section><section class="card">${cardHead('','Export contract')}<div class="card-body"><div class="reference-item"><strong>trix.environment-planning/v1</strong><p>A configurator-specific schema containing revision, policy, groups, workload, diagnostics and implementation sequence. It does not replace normative task-plan schemas.</p></div><div class="reference-item"><strong>English throughout</strong><p>The interface, JSON, YAML, implementation brief, diagnostic codes and technical documentation all use English.</p><span class="trace">IDN-001 · IDN-005 · CON-005</span></div><div class="reference-item"><strong>Source baseline</strong><p>TriX_Design_and_Implementation_Standard_v0_2.md · 22 October 2026 · proposed normative baseline. Formal adoption and qualification remain outstanding.</p></div></div></section></div>`;}
let conversation=[],pendingProposal=null;
function commands(){return heading('Plan through dialogue.','Local command mode · deterministic planning tools · no model connected','','AGENT WORKSPACE')+`<div class="main-grid"><section class="card"><div class="card-body"><p class="note-box">Active tools can prepare profiles, validate compatibility and generate planning configurations. External execution, audits and open-ended AI reasoning are not connected.</p><div class="agent-log" role="log" aria-live="polite">${conversation.map(m=>`<article class="reference-item"><strong>${esc(m.role)}</strong><p style="white-space:pre-wrap">${esc(m.text)}</p></article>`).join('')||'<p>Start with “profile cpu”, then “offline on”, “validate” and “generate”.</p>'}</div><form id="agent-form"><label for="command-prompt">Your request</label><textarea id="command-prompt" rows="3" maxlength="2000" required placeholder="profile cpu"></textarea><button class="primary" type="submit">Send request</button></form>${pendingProposal?'<p>Review the proposed change above before applying it.</p><button class="primary" id="agent-apply">Apply proposed configuration</button> <button class="secondary" id="agent-discard">Discard</button>':''}<div class="actions" style="margin-top:16px"><button class="secondary" data-go="configure">Review environment</button><button class="secondary" data-go="plan">View technical configuration</button><button class="secondary" id="agent-clear">Clear dialogue</button></div></div></section><aside><section class="card">${cardHead('','Skills & integration evidence','Availability is separate from runtime installation')}<div class="card-body">${skills.map(s=>`<div class="reference-item"><strong>${esc(s.id)}</strong><p><span class="badge purple">${esc(s.status)}</span></p><small>${esc(s.kind)}</small><p>${esc(s.scope)}</p></div>`).join('')}</div></section></aside></div>`;}
function bindAgents(){
 $('#agent-form')?.addEventListener('submit',e=>{e.preventDefault();const prompt=$('#command-prompt').value;const result=respond(prompt,state);conversation.push({role:'You',text:prompt},{role:result.agent||'TriX coordinator',text:result.message});conversation=conversation.slice(-40);pendingProposal=result.status==='proposed'?{...result,base:JSON.stringify(state)}:null;render();$('#command-prompt')?.focus();});
 $('#agent-apply')?.addEventListener('click',()=>{try{previousScenario=structuredClone(state);state=applyProposal(pendingProposal,state);persist();conversation.push({role:'TriX coordinator',text:'Configuration applied. You can restore the previous scenario in Configure environment.'});}catch(e){conversation.push({role:'TriX coordinator',text:e.message});}pendingProposal=null;render();});
 $('#agent-discard')?.addEventListener('click',()=>{pendingProposal=null;conversation.push({role:'TriX coordinator',text:'Proposal discarded. No scenario change.'});render();});
 $('#agent-clear')?.addEventListener('click',()=>{conversation=[];pendingProposal=null;render();});
}
function render(){const opened=[...document.querySelectorAll('details[open]')].map(e=>({group:e.closest('[data-group-card]')?.dataset.groupCard,text:e.querySelector('summary')?.textContent}));document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===active);b.setAttribute('aria-current',b.dataset.tab===active?'page':'false');});$('#breadcrumb').textContent=labels[active];$('#compare-count').textContent=comparisons.length;$('#view').innerHTML=({commands,agents,overview,configure,compare,plan,reference}[active])();for(const d of document.querySelectorAll('details'))if(opened.some(o=>o.group===d.closest('[data-group-card]')?.dataset.groupCard&&o.text===d.querySelector('summary')?.textContent))d.open=true;bind();}
function go(v){active=v;render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
function change(key,value,id){const target=id?state.groups.find(g=>g.id===id):state;target[key]=value;selectedPreset='';persist();render();}
function liveInput(el){const target=el.dataset.group?state.groups.find(g=>g.id===el.dataset.group):state;target[el.dataset.key]=el.type==='number'?Number(el.value):el.value;selectedPreset='';document.querySelectorAll('[data-preset]').forEach(b=>b.classList.remove('selected'));persist();const result=validate(state);const panel=$('#live-validation');if(panel){panel.innerHTML=validationPanel(result);panel.querySelector('[data-action="generate"]')?.addEventListener('click',()=>{if(!validate(state).errors)go('plan');});}const statPanel=$('.stats');if(statPanel)statPanel.outerHTML=stats(result);for(const article of document.querySelectorAll('[data-group-card]')){const group=state.groups.find(g=>g.id===article.dataset.groupCard);const issues=assessGroup(group,state);article.querySelector('.group-title h3').innerHTML=`<span class="index">G${String(state.groups.indexOf(group)+1).padStart(2,'0')}</span>${esc(group.name)}`;article.querySelector('.group-title .badge').outerHTML=statusBadge({errors:issues.filter(x=>x.level==='error').length,warnings:issues.filter(x=>x.level==='warning').length});}}
function download(){const content=planText(),ext=format==='brief'?'md':format;const url=URL.createObjectURL(new Blob([content],{type:format==='json'?'application/json':'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='TriX_Environment_Configuration.'+ext;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('Configuration exported as '+ext.toUpperCase()+'.');}
async function copyConfiguration(){const text=planText();if(navigator.clipboard?.writeText){try{await navigator.clipboard.writeText(text);return;}catch{}}const area=document.createElement('textarea');area.value=text;area.setAttribute('aria-hidden','true');area.style.position='fixed';area.style.left='-9999px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();if(!ok)throw new Error('Clipboard unavailable');}
function snapshot(){if(comparisons.length>=4){toast('Four-scenario limit reached. Remove a snapshot to save another.');return;}comparisons.push(structuredClone(state));persist();toast('Scenario saved for comparison.');render();}
function bind(){bindAgents();
$('#agent-prompt')?.addEventListener('input',e=>{agentPrompt=e.target.value;});
document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{agentPrompt=b.dataset.example;agentDraft=false;render();$('#agent-prompt').focus();}));
document.querySelectorAll('[data-agent]').forEach(b=>b.addEventListener('click',()=>{agentPrompt=$('#agent-prompt')?.value||agentPrompt;selectedAgent=b.dataset.agent;render();}));
document.querySelectorAll('input[data-key]:not([type=checkbox])').forEach(el=>el.addEventListener('input',()=>liveInput(el)));document.querySelectorAll('[data-key]').forEach(el=>el.addEventListener('change',()=>change(el.dataset.key,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value,el.dataset.group)));document.querySelectorAll('[data-preset]').forEach(el=>el.addEventListener('click',()=>{previousScenario=structuredClone(state);state=preset(el.dataset.preset);selectedPreset=el.dataset.preset;persist();render();toast('Profile applied. All choices remain editable.');}));document.querySelectorAll('[data-go]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.go)));document.querySelectorAll('[data-format]').forEach(el=>el.addEventListener('click',()=>{format=el.dataset.format;render();}));$('#matrix-group')?.addEventListener('change',e=>{matrixGroup=Number(e.target.value);render();});document.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',async()=>{const act=el.dataset.action;switch(act){case 'prepare-brief':agentPrompt=$('#agent-prompt').value.trim();if(!agentPrompt){toast('Describe an outcome first.');$('#agent-prompt').focus();break;}agentDraft=true;render();break;case 'undo-profile':if(previousScenario){state=previousScenario;previousScenario=null;selectedPreset='';persist();render();toast('Previous scenario restored.');}break;case 'generate':if(!validate(state).errors)go('plan');break;case 'import':$('#import-dialog').showModal();break;case 'snapshot':snapshot();break;case 'add':if(state.groups.length<8){state.groups.push(node({id:'group-'+(crypto.randomUUID?.()||Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,10)),name:'Execution group '+(state.groups.length+1)}));persist();render();}break;case 'remove':if(state.groups.length>1){state.groups=state.groups.filter(g=>g.id!==el.dataset.id);persist();render();}break;case 'load':state=structuredClone(comparisons[Number(el.dataset.index)]);persist();go('configure');toast('Scenario restored and validated again.');break;case 'delete-snapshot':comparisons.splice(Number(el.dataset.index),1);persist();render();break;case 'download':download();break;case 'copy':try{await copyConfiguration();toast('Configuration copied.');}catch{toast('Clipboard unavailable. Use Export instead.');}break;}}));}
document.querySelectorAll('[data-tab]').forEach(el=>el.addEventListener('click',()=>go(el.dataset.tab)));
$('#import-file').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>250000){$('#import-error').textContent='File exceeds 250 KB.';return;}$('#import-text').value=await f.text();$('#import-error').textContent='';});
$('#import-confirm').addEventListener('click',()=>{try{state=importConfig($('#import-text').value);selectedPreset='';persist();$('#import-dialog').close();go('configure');toast('Configuration imported and validated again.');}catch(e){$('#import-error').textContent='Unable to import: '+e.message;}});
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
let themeChoice='system';try{themeChoice=localStorage.getItem('trix.theme')||'system';}catch{}
if(!['light','dark','system'].includes(themeChoice))themeChoice='system';
function applyTheme(){document.documentElement.dataset.theme=themeChoice==='system'?(themeMedia.matches?'dark':'light'):themeChoice;$('#theme-select').value=themeChoice;}
$('#theme-select').addEventListener('change',e=>{themeChoice=e.target.value;try{localStorage.setItem('trix.theme',themeChoice);}catch{}applyTheme();});
themeMedia.addEventListener('change',()=>{if(themeChoice==='system')applyTheme();});
applyTheme();render();
